+    const allSelected = inputs.every(c => c.checked);
+    for (const checkbox of inputs.filter(c => !c.disabled)) {
       checkbox.checked = !allSelected;
-    });
-
-    this.counterObserver[type] = allSelected
-      ? 0
-      : this.#availableSyncAccounts[type].length;
+    }
